                    person.unretire(r.to());
                });
            }
            if (p.retiredFrom() != null) {
                person.retire(p.retiredFrom());
            }
            people.put(p.id(), person);
        }
        Map<Long, Claim> claims = new LinkedHashMap<>();
        for (ClaimState c : state.claims()) {
            Claim claim = new Claim(now.getId(), c.personId(), c.amount(), c.date(), 0, c.dueBy(), "", c.corrects());
            claim.become(c.status());
            claim.number(c.number());
            claim.settleDue(c.settledDue());
            if (c.stated()) {
                claim.bind(c.statedDue(), Boolean.TRUE.equals(c.statedWhole()));
            }
            claim.defer(c.deferredUntil());
            claim.keepAdded(c.added());
            if (Boolean.TRUE.equals(c.waived())) {
                claim.waive();
            }
            claims.put(c.id(), claim);
        }
        Dues.Basis basis = new Dues.Basis(sheet, rates, inherited, correction -> claims.values().stream()
                .filter(c -> Objects.equals(c.getPersonId(), correction.getPersonId())
                        && Objects.equals(c.getNumber(), correction.getCorrects()))
                .findFirst());
        return new AsOf(sheet, people, claims, basis);
    }

    /** The rates kept in a sheet's state, held in no store. */
    private static List<Rate> rates(String sheetId, State state) {
        return state.rates().stream().map(r -> {
            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.pct());
            rate.setToDate(r.to());
            rate.setForwardAfter(r.forwardAfter());
            if (r.older() != null) {
                rate.keepOlder(r.older().stream()
                        .map(v -> new RateVersion(null, v.version(), v.pct(), v.to(), v.forwardAfter())).toList());
            }
            return rate;
        }).toList();
    }

    private static PersonState kept(Person p) {
        return new PersonState(p.getId(), p.getName(), p.getGrade(),
                p.getGradesFrom().entrySet().stream().map(e -> new GradeState(e.getKey(), e.getValue())).toList(),
                p.getTerms(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
                p.getRetiredFrom(), p.getContact(), p.getAliases(),
                p.getRetirements().stream().map(r -> new RetirementState(r.getFromDate(), r.getToDate())).toList(),
                p.getTermsFrom().entrySet().stream().map(e -> new TermsState(e.getKey(), e.getValue())).toList());
    }

    private static RateState kept(Rate r) {
        return new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getPct(), r.getForwardAfter(),
                r.getOlder().stream().map(v -> new RateVersionState(v.getVersion(), v.getPct(), v.getToDate(),
                        v.getForwardAfter())).toList());
    }

    private static ClaimState kept(Claim c) {
        return new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(), c.getDueBy(), c.getStatus(),
                c.getNumber(), c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getCorrects(), c.getDeferredUntil(), c.getAdded(),
                c.isWaived(), c.isStatedWhole());
    }
}

        // Claims are added in the order they are listed, so the clone lists them the same; none is
        // bound by a statement there, and none is held by an editor.
        Map<Long, Long> cloned = new HashMap<>();
        jdbc.query("SELECT id, person_id FROM claim WHERE sheet_id = ? ORDER BY listed, id", row -> {
            long from = row.getLong(1);
            long to = insert("""
                    INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, settled_due, opened_by,
                        edited_by, settle_batch, corrects, due_by, terms, due_from, deferred_until, proofs, proofs_receipt, proofs_photo, split_from,
                        late_entry, reminded_on, escalated, ref, ref_key, tags, tags_used, void_reason, added_seq, waived)
                    SELECT ?, ?, amount, claim_date, note, status, settled_due, opened_by,
                        edited_by, settle_batch, corrects, due_by, terms, due_from, deferred_until, proofs, proofs_receipt, proofs_photo, split_from,
                        late_entry, reminded_on, escalated, ref, ref_key, tags, tags_used, void_reason, added_seq, waived
                    FROM claim WHERE id = ?""", toSheetId, people.get(row.getLong(2)), from);
            copyChildren("claim_log", "claim_id", "status, by_user, on_date, due", to, from);
            copyChildren("claim_comment", "claim_id", "by_user, on_date, text", to, from);
            copyChildren("claim_line", "claim_id", "label, qty, unit", to, from);
            cloned.put(to, from);
        }, sheetId);

        // Each claim that had a number takes the clone's next, in the order the originals were opened.
     * What the screen is told about a claim; the amount with two decimals, and the due fixed when it
     * was settled (null when not fixed, so its due is worked out from the current rate), and who
     * opened it (null until opened), and whether it is bound by its person's last statement, with the
     * figure it was bound to (null when unbound, or when it was n/a), and the number of the claim it
     * corrects (null unless it is a correction), and the date it is due by, fixed when it was added, and its status
     * log, oldest first, and the date it is deferred until (null when it was never deferred), and its proofs count,
     * and the number of the claim it was split from (null unless it was split off another), and the user whose open
     * editor locks it (null when none does), and the last day it was reminded (null when never), and its
     * external reference (null when it has none), and its tags, sorted, and every tag it has ever carried, sorted,
     * and the reason it was voided with (null when none), and its comments, oldest first, and the user who last edited it (null when never), and the number of the bulk settle batch that settled
     * it (null when none did), and its lines, in the order they were added, and whether its late charge was waived, and whether the
     * figure it was bound to is its whole due as shown (late charge and floor included), and its proofs count of each kind.
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, List<LogLineView> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn,
            String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<CommentView> comments,
            String editedBy, Integer settleBatch, List<LineView> lines, Long added, boolean waived,
            boolean statedWhole, int proofsReceipt, int proofsPhoto) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(), claim.getRemindedOn(),
                    claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentView::of).toList(), claim.getEditedBy(),
                    claim.getSettleBatch(), claim.getLines().stream().map(LineView::of).toList(), claim.getAdded(),
                    claim.isWaived(), claim.isStatedWhole(), claim.getProofs("receipt"), claim.getProofs("photo"));
        }
    }

    /** A line of a claim's status log; the due with two decimals, or n/a. */
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.remind(sheetId, SignedIn.name(user), claimId));
    }

    /** Waive an OPEN or PENDING claim's late charge; only a steward. */
    @PostMapping("/claims/{claimId}/waive")
    public ClaimView waive(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.waive(sheetId, SignedIn.name(user), claimId));
    }

